:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --primary: #f5c2e7;
  --accent: #89b4fa;
  --text: #cdd6f4;
  --light-off: #45475a;
  --light-on: #f9e2af;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.metronome-card {
  background: var(--card-bg);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 0.05em;
}

.bpm-control {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.bpm-value {
  font-size: 2rem;
  font-weight: 700;
  min-width: 7ch;
  text-align: center;
  color: var(--accent);
}

.control-btn {
  background: var(--light-off);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 1.25rem;
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-width: 3rem;
  min-height: 3rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.control-btn:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

.control-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.control-btn:active:not(:disabled) {
  transform: scale(0.95);
  background: var(--primary);
  color: var(--bg);
}

.control-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.transport {
  display: flex;
  gap: 1rem;
}

.start {
  background: var(--accent);
  color: var(--bg);
}

.stop {
  background: var(--light-off);
}

.beat-section {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.beat-light {
  width: 4rem;
  height: 4rem;
  border-radius: 50%;
  background: var(--light-off);
  transition: background 0.05s, box-shadow 0.05s;
}

.beat-light.on {
  background: var(--light-on);
  box-shadow: 0 0 24px var(--light-on);
}

.beat-counter {
  font-size: 1.25rem;
  font-weight: 600;
}

@media (max-width: 400px) {
  .metronome-card {
    padding: 1.5rem 1rem;
  }
  .bpm-value {
    font-size: 1.5rem;
  }
  .control-btn {
    padding: 0.6rem 1rem;
    font-size: 1.1rem;
  }
  .beat-light {
    width: 3rem;
    height: 3rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beat-light {
    transition: none;
  }
  .control-btn {
    transition: none;
  }
}

(function () {
  'use strict';

  const MIN_BPM = 40;
  const MAX_BPM = 200;
  const DEFAULT_BPM = 120;

  let bpm = DEFAULT_BPM;
  let beatCount = 0;
  let isRunning = false;
  let timerId = null;
  let nextTick = 0;
  let lightTimeout = null;

  const bpmDisplay = document.getElementById('bpm-display');
  const bpmMinus = document.getElementById('bpm-minus');
  const bpmPlus = document.getElementById('bpm-plus');
  const startBtn = document.getElementById('start-btn');
  const stopBtn = document.getElementById('stop-btn');
  const beatLight = document.getElementById('beat-light');
  const beatCounter = document.getElementById('beat-counter');

  function updateBpmDisplay() {
    bpmDisplay.textContent = bpm + ' BPM';
  }

  function setBpm(newBpm) {
    bpm = Math.min(MAX_BPM, Math.max(MIN_BPM, newBpm));
    updateBpmDisplay();
    if (isRunning) {
      restartTimer();
    }
  }

  function flashLight() {
    beatLight.classList.add('on');
    if (lightTimeout) clearTimeout(lightTimeout);
    lightTimeout = setTimeout(function () {
      beatLight.classList.remove('on');
    }, 100);
  }

  function tick() {
    beatCount++;
    beatCounter.textContent = 'Beats: ' + beatCount;
    flashLight();
    scheduleNextTick();
  }

  function scheduleNextTick() {
    if (!isRunning) return;
    const interval = 60000 / bpm;
    const now = performance.now();
    nextTick += interval;
    const delay = Math.max(0, nextTick - now);
    timerId = setTimeout(tick, delay);
  }

  function start() {
    if (isRunning) return;
    isRunning = true;
    beatCount = 0;
    beatCounter.textContent = 'Beats: 0';
    startBtn.disabled = true;
    stopBtn.disabled = false;
    nextTick = performance.now();
    tick();
  }

  function stop() {
    if (!isRunning) return;
    isRunning = false;
    clearTimeout(timerId);
    timerId = null;
    if (lightTimeout) {
      clearTimeout(lightTimeout);
      lightTimeout = null;
    }
    beatLight.classList.remove('on');
    startBtn.disabled = false;
    stopBtn.disabled = true;
  }

  function restartTimer() {
    clearTimeout(timerId);
    timerId = null;
    nextTick = performance.now();
    scheduleNextTick();
  }

  bpmMinus.addEventListener('click', function () {
    setBpm(bpm - 1);
  });

  bpmPlus.addEventListener('click', function () {
    setBpm(bpm + 1);
  });

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  updateBpmDisplay();
})();
